"""A JSON argument given as text, as an object, or as the path of a file.

A run wrote its DesignPlan to ``Design Notes\\schematic_plan.json`` and
passed that path, as boardwright_draft_schematic takes it, to
design_validate_plan and sch_draw_template; both answered "invalid JSON:
Expecting value: line 1 column 1" (live run 2026-11-09). A plan of 17
parts is also large to send inline on every call.
"""
from __future__ import annotations

import os
from typing import Any


def json_text(value: Any) -> Any:
    """``value`` itself, unless it is a path to an existing .json file:
    then that file's text. Anything else (an object, inline JSON) is
    returned unchanged for the caller to parse."""
    if not isinstance(value, str):
        return value
    text = value.strip().strip('"')
    if (text and text[0] not in "{[" and text.lower().endswith(".json")
            and os.path.isfile(text)):
        with open(text, encoding="utf-8-sig") as fh:
            return fh.read()
    return value
